using SchoolERP.Application.Abstractions;namespace SchoolERP.Api.Logging;public sealed class AuthenticatedRequestContextMiddleware(RequestDelegate next){public async Task InvokeAsync(HttpContext c,ILogger<AuthenticatedRequestContextMiddleware> logger,ICurrentUser user,ICurrentTenant tenant){using(logger.BeginScope(new Dictionary<string,object?>{{"UserId",user.UserId},{"TenantId",tenant.IsAvailable?tenant.TenantId:null},{"SchoolId",user.SchoolId},{"CampusId",user.CampusId},{"Method",c.Request.Method},{"Path",c.Request.Path.Value}})){await next(c);}}}
